/bin/bash -lc "python3 - <<'PY'
import json, subprocess
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
print('ROOT KEYS',list(r))
for k,v in r.items():
 if k"'!='"'context': print(k,json.dumps(v))
c=r.get('context',{})
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ('history','knowledge'): print(k,json.dumps(v))
print('HISTORY SUMMARY')
for t in c.get('history',[]):
 print(json.dumps({k:t.get(k) for k in ['id','parent','role','status','config','wall_seconds','parameters','error','note']}))
 print(json.dumps(t.get('validation',{})))
PY"

