/bin/bash -lc "python3 - <<'PY'
import ast, copy, hashlib, json, subprocess
from pathlib import Path
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
p=json.loads(Path('proposal.json').read_text())
def validate(x,s,path='"'$'"'):
 t=s.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
 if t: assert isinstance(x,types[t]),(path,t)
 if 'const' in s:assert x==s['const'],path
 if 'enum' in s:assert x in s['enum'],path
 if t=='string':assert len(x)>=s.get('minLength',0),path
 if t=='object':
  assert set(s.get('required',[]))<=x.keys(),(path,'missing required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False:assert x.keys()<=props.keys(),(path,'extra fields')
  for k,v in x.items():
   if k in props:validate(v,props[k],path+'.'+k)
 if t=='array':
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s.get('items',{}),path+'['+str(i)+']')
validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
normalized=[]
for v in p['variants']:
 file=v['file'];assert Path(file).name==file and file.endswith('.py')
 s=Path(file).read_text();compile(s,file,'exec');tree=ast.parse(s)
 node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(node.value)==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in init.args.args[-len(init.args.defaults):]],init.args.defaults))
 for k,value in v['config'].items():
  actual=ast.literal_eval(defaults[k]);assert (list(actual) if isinstance(actual,tuple) else actual)==value,(file,k)
 assert hashlib.sha256(s.encode()).hexdigest() in v['note']
 assert {n.module.split('.')[0] for n in ast.walk(tree) if isinstance(n,ast.ImportFrom)} <= {'torch','unirank'}
 assert {a.name.split('.')[0] for n in ast.walk(tree) if isinstance(n,ast.Import) for a in n.names} <= {'torch','copy','math'}
 for n in ast.walk(tree):
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','__import__'}
 # Factorial sources may differ only at literal configuration/constructor defaults.
 node.value=ast.Constant(value=None)
 for key in ['gate_scope','gate_feedback_identity']:
  index=[a.arg for a in init.args.args].index(key)-(len(init.args.args)-len(init.args.defaults))
  init.args.defaults[index]=ast.Constant(value=None)
 normalized.append(ast.dump(tree,include_attributes=False))
 print(file,'static checks passed',hashlib.sha256(s.encode()).hexdigest())
assert len(set(normalized))==1,'Unplanned source differences between variants'
parent_tree=ast.parse(Path('history_g3_r0008_feedback_match_evidence.py').read_text())
parent_cls=next(n for n in parent_tree.body if isinstance(n,ast.ClassDef))
for name in ['_history_scores','_private_item_embeddings']:
 a=next(n for n in parent_cls.body if isinstance(n,ast.FunctionDef) and n.name==name)
 b=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name==name)
 assert ast.dump(a,include_attributes=False)==ast.dump(b,include_attributes=False)
expected={'unirank-method-'+n for n in ['hiformer','rankmixer','infnet','longer','onetrans','zenith','hyformer','mixformer','tokenmixer','est','hemix','unimixer','tokenformer','ultrahstu','ssr']}
assert expected<={a['knowledge_id'] for a in p['knowledge_assessments']}
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
for a in p['knowledge_assessments']:
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<={v['name'] for v in p['variants']}
print('proposal study schema, evidence IDs, protocol, variant interface, knowledge coverage, hashes and factorial equivalence: PASS')
print('Inherited score-gradient and private-embedding methods are AST-identical to archived parent.')
print('Dynamic checks and performance remain pending host execution; no training performed.')
PY"

